export const allMenuItems = restaurants.flatMap((r) =>
  r.menu.map((item) => ({ ...item, restaurantName: r.name, restaurantSlug: r.slug }))
);

// Every cuisine that actually appears on a restaurant, with a representative
// image (from the curated categories list when available, otherwise the
// first restaurant of that cuisine) and a live count of restaurants
// serving it — used to power cuisine search/suggestions and the cuisine
// filter dropdown so neither ever drifts out of sync with the restaurant data.
export const allCuisines = [...new Set(restaurants.flatMap((r) => r.cuisines))]
  .sort()
  .map((name) => {
    const fromCategories = categories.find((c) => c.name === name);
    const restaurantsOfCuisine = restaurants.filter((r) => r.cuisines.includes(name));
    return {
      name,
      image: fromCategories?.image || restaurantsOfCuisine[0]?.image,
      count: restaurantsOfCuisine.length,
    };
  });
